// ❌ OLD: A manual .pipe() chain. If gunzip or parser emits an error,
// the error is NOT propagated to the rest of the chain: the writable
// 'out' stays open, the readable may keep flowing, and the process can
// hang or leak resources. You'd need to attach error handlers to EVERY
// stream and manually destroy the chain — easy to miss.
const { createReadStream, createWriteStream } = require('node:fs');
const { gunzip } = require('node:zlib');

const readable = createReadStream('data.gz');
const out = createWriteStream('out.txt');

readable.pipe(gunzip).pipe(out); // ❌ OLD: no central error handling

// If the file is corrupt, gunzip errors but out may never close.
// Manual fix would be:
// readable.on('error', ...); gunzip.on('error', ...); out.on('error', ...);
// and coordinating destroy on each — error-prone boilerplate.

const { pipeline } = require('node:stream/promises');
const { createReadStream, createWriteStream } = require('node:fs');
const { gunzip } = require('node:zlib');

async function processFile() {
  // ✅ NEW: one call composes the chain, respects backpressure, and on
  // ANY stream error destroys the whole chain and rejects the promise.
  await pipeline(
    createReadStream('data.gz'), // ✅ NEW: source
    gunzip(), // ✅ NEW: transform stage
    createWriteStream('out.txt') // ✅ NEW: destination
  );
}

processFile().catch((err) => {
  console.error('processing failed:', err);
  process.exitCode = 1;
});

